## TitleText1()
## EditionText1()
## AuthorText1()
## Section1(not reported)
## Problem1(1.3.5.6)
## Author()
## Institution()
## Language(en-US)

DOCUMENT();

############################################################
# Load Macros
############################################################
loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "PCCmacros.pl",
  "bizarroArithmetic.pl",
  "contextForm.pl",
  "APEX.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

############################################################
# Header
############################################################

############################################################
# PG Setup Code
############################################################
$lb = random(-3,-1,1);
$ub = random(1,3,1);
$m = random(2,5,1);
$b = non_zero_random(-3,3,1);
if($envir{problemSeed}==1){$lb=-1;$ub=3;$m=4;$b=-2;};
Context()->variables->are(i=>'Real');
$f = Formula("$m i + $b")->reduce;
@i = ($lb..$ub);
@fi = map{$m*$_ + $b}(@i);
$string = join('+',@fi);
$sum = Real($string);
Context("Form");
Context()->operators->set(
  '+' => {class => 'bizarro::BOP::add', isCommand => 1},
  '-' => {class => 'bizarro::BOP::subtract', isCommand => 1},
);
$terms = Formula("$string");

############################################################
# Body
############################################################

BEGIN_PGML
Write out each term of the summation and compute the sum.

[`\sum\limits_{i=[$lb]}^{[$ub]} \left([$f]\right)`]

[@KeyboardInstructions('Enter the sum of terms here. For example, [|1+2+3|]*.')@]**

[_]{$terms}{20}

[@KeyboardInstructions('Enter the actual sum here.')@]**

[_]{$sum}{20}

END_PGML

############################################################
# End Problem
############################################################

ENDDOCUMENT();
